 'icon-button': {sizes:['Default','Small'],states:['Default','Disabled','Read only','Loading'],tokens:[...contracts.action.tokens,'icon-button-small-size'],responsive:'Default follows the same control height as Button. Small uses the semantic small-icon target. Both retain the shared minimum touch target on coarse pointers.'},
